/**
 * Mercenary catalog (PoE 1, 3.30): what can roll on a warrant, per family. Generated by
 * scripts/poe1-mercenary-catalog.mjs from PoEDB (game data) and the official Trade stat list;
 * shipped with the app and registered in the Update Center as `poe1.mercenary-catalog`.
 *
 * Canonical ids (slugs) are used everywhere; display names are only for matching text. What can
 * roll (this catalog) is kept apart from what is on a warrant (`ParsedWarrant`).
 */
import raw from "./data/catalog-3.30.json";

export type SkillCategory = "primary" | "secondary" | "utility";

export interface CatalogSkillRule {
  category: SkillCategory;
  /** Only when the skill's text has more than one official stat (Herald of Ash). */
  stat?: string;
  supportCount: string | null;
  levelRange: [number, number] | null;
  requires: string[];
  /** Compact "support:tiers[@tier=stat]" entries, decoded by `allowedSupports`. */
  supports: string[];
}

export interface CatalogVariant {
  id: string;
  name: string;
  infamous: boolean;
  warrantType: string;
  poedb: string;
  pools: Record<SkillCategory, string[]>;
  skills?: Record<string, CatalogSkillRule>;
}

export interface CatalogFamily {
  id: string;
  name: string;
  house: string | null;
  attributes: string[];
  classTag: string | null;
  weapons: string[];
  variants: CatalogVariant[];
  /** Shared skill rules when every variant has the same ones (checked by the generator). */
  skills: Record<string, CatalogSkillRule> | null;
}

export interface CatalogSkill {
  id: string;
  name: string;
  trarthus: boolean;
  vaal: boolean;
  stats: string[];
}

export interface CatalogSupport {
  id: string;
  name: string;
  tiers: Record<string, { display: string; stats: string[] }>;
}

export interface CatalogMeta {
  schema: number;
  catalogVersion: string;
  gameVersion: string;
  league: string;
  platform: string;
  generatedAt: string;
  sources: { url: string; fetchedAt: string }[];
  licence: string;
  counts: Record<string, number>;
  problems: string[];
}

export interface Catalog {
  meta: CatalogMeta;
  families: CatalogFamily[];
  skills: CatalogSkill[];
  supports: CatalogSupport[];
}

export const CATALOG = raw as unknown as Catalog;
export const CATALOG_META = CATALOG.meta;

export interface AllowedSupport {
  support: string;
  tiers: number[];
  /** tier → stat id when it depends on the owning skill */
  statOverride: Record<number, string>;
}

const norm = (s: string) =>
  s
    .toLowerCase()
    .replace(/[’`]/g, "'")
    .replace(/\s+/g, " ")
    .trim();

export class CatalogIndex {
  readonly familyById = new Map<string, CatalogFamily>();
  readonly variantByBuild = new Map<string, { family: CatalogFamily; variant: CatalogVariant }>();
  readonly variantByType = new Map<string, { family: CatalogFamily; variant: CatalogVariant }>();
  readonly skillById = new Map<string, CatalogSkill>();
  readonly skillByName = new Map<string, CatalogSkill>();
  readonly skillByStat = new Map<string, CatalogSkill>();
  readonly supportById = new Map<string, CatalogSupport>();
  /** normalized display name → [{support, tier}] (a display name is unique per tier) */
  readonly supportByDisplay = new Map<string, { support: CatalogSupport; tier: number }[]>();
  readonly supportByStat = new Map<string, { support: CatalogSupport; tier: number }>();

  constructor(readonly catalog: Catalog) {
    for (const f of catalog.families) {
      this.familyById.set(f.id, f);
      for (const v of f.variants) {
        this.variantByBuild.set(norm(v.name), { family: f, variant: v });
        this.variantByType.set(v.warrantType, { family: f, variant: v });
      }
    }
    for (const s of catalog.skills) {
      this.skillById.set(s.id, s);
      this.skillByName.set(norm(s.name), s);
      for (const st of s.stats) this.skillByStat.set(st, s);
    }
    for (const s of catalog.supports) {
      this.supportById.set(s.id, s);
      for (const [t, info] of Object.entries(s.tiers)) {
        const key = norm(info.display);
        const list = this.supportByDisplay.get(key) ?? [];
        list.push({ support: s, tier: Number(t) });
        this.supportByDisplay.set(key, list);
        for (const st of info.stats) this.supportByStat.set(st, { support: s, tier: Number(t) });
      }
    }
  }

  build(label: string) {
    return this.variantByBuild.get(norm(label)) ?? null;
  }

  skill(name: string) {
    return this.skillByName.get(norm(name)) ?? null;
  }

  /** Every (support, tier) whose display text is `name` — usually exactly one. */
  supportsNamed(name: string) {
    return this.supportByDisplay.get(norm(name)) ?? [];
  }

  skillRules(family: CatalogFamily, variant: CatalogVariant | null): Record<string, CatalogSkillRule> {
    return variant?.skills ?? family.skills ?? family.variants[0]?.skills ?? {};
  }

  skillRule(family: CatalogFamily, variant: CatalogVariant | null, skillId: string): CatalogSkillRule | null {
    return this.skillRules(family, variant)[skillId] ?? null;
  }

  allowedSupports(rule: CatalogSkillRule): AllowedSupport[] {
    return rule.supports.map((entry) => {
      const [head = "", ...overrides] = entry.split("@");
      const [support = "", tiers = ""] = head.split(":");
      const statOverride: Record<number, string> = {};
      for (const o of overrides) {
        const [t, stat] = o.split("=");
        if (stat) statOverride[Number(t)] = stat;
      }
      return { support, tiers: [...tiers].map(Number), statOverride };
    });
  }

  /** Official stat id of a skill on a family (null when unknown). */
  skillStat(family: CatalogFamily, variant: CatalogVariant | null, skillId: string): string | null {
    const rule = this.skillRule(family, variant, skillId);
    if (rule?.stat) return rule.stat;
    const s = this.skillById.get(skillId);
    return s && s.stats.length === 1 ? (s.stats[0] ?? null) : null;
  }

  /** Official stat id of a support tier on its owning skill (null when unknown / not rollable). */
  supportStat(family: CatalogFamily, variant: CatalogVariant | null, skillId: string, supportId: string, tier: number): string | null {
    const rule = this.skillRule(family, variant, skillId);
    const allowed = rule ? this.allowedSupports(rule).find((a) => a.support === supportId) : null;
    const override = allowed?.statOverride[tier];
    if (override) return override;
    const stats = this.supportById.get(supportId)?.tiers[tier]?.stats ?? [];
    return stats.length === 1 ? (stats[0] ?? null) : null;
  }

  displayOf(supportId: string, tier: number) {
    return this.supportById.get(supportId)?.tiers[tier]?.display ?? supportId;
  }

  skillName(id: string) {
    return this.skillById.get(id)?.name ?? id;
  }
}

let index: CatalogIndex | null = null;
export const catalogIndex = () => (index ??= new CatalogIndex(CATALOG));
